package money

import (
	"strconv"
	"strings"
)

// FormatPrice renders cents as a dollar amount, e.g. 1234 -> "$12.34",
// -5 -> "-$0.05".
func FormatPrice(cents int64) string {
	neg := cents < 0
	abs := uint64(cents)
	if neg {
		abs = uint64(-cents)
	}

	dollars := abs / 100
	remainder := abs % 100

	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	b.WriteByte('$')
	b.WriteString(strconv.FormatUint(dollars, 10))
	b.WriteByte('.')
	if remainder < 10 {
		b.WriteByte('0')
	}
	b.WriteString(strconv.FormatUint(remainder, 10))
	return b.String()
}

