package money

import (
	"math"
	"testing"
)

func TestFormatPrice(t *testing.T) {
	cases := []struct {
		cents int64
		want  string
	}{
		{0, "$0.00"},
		{1234, "$12.34"},
		{-5, "-$0.05"},
		{100, "$1.00"},
		{-100, "-$1.00"},
		{9, "$0.09"},
		{-1, "-$0.01"},
		{1000000, "$10000.00"},
		{math.MinInt64, "-$92233720368547758.08"},
		{math.MaxInt64, "$92233720368547758.07"},
	}

	for _, c := range cases {
		if got := FormatPrice(c.cents); got != c.want {
			t.Errorf("FormatPrice(%d) = %q, want %q", c.cents, got, c.want)
		}
	}
}

